<?php
require_once __DIR__.'/verification_views.php';
function renderHeader(string $page): void {$titles=['dashboard'=>'Panel','vehicles'=>'Vehículos','vehicle'=>'Vehículo','trip_form'=>'Bitácora','trip'=>'Bitácora','fuel'=>'Gasolina','reservations'=>'Programación','reservation_form'=>'Programación','reports'=>'Concentrados','gaps'=>'Km pendientes','import'=>'Importar','users'=>'Usuarios externos','profile'=>'Mi perfil','records'=>'Registros','login'=>'Acceso'];?><!DOCTYPE html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($titles[$page]??'Control vehicular')?> · Control vehicular</title><link rel="stylesheet" href="assets/app.css?v=2.9"><script src="assets/app.js?v=2.9" defer></script></head><body><?php if($page!=='login'):?><aside class="sidebar"><a class="brand" href="<?=e(url('dashboard'))?>"><span class="brand-mark">CV</span><span>Control<br><strong>vehicular</strong></span></a><div class="nav-caption"><?=isAdmin()?'ADMINISTRACIÓN':'USUARIO'?></div><nav><?php $nav=isAdmin()?['dashboard'=>['Panel','◫'],'vehicles'=>['Vehículos','▣'],'fuel'=>['Gasolina','⛽'],'reservations'=>['Programación','▦'],'reports'=>['Concentrados','▤'],'gaps'=>['Kilómetros pendientes','↔'],'import'=>['Importar','↥'],'users'=>['Usuarios externos','♙']]:['dashboard'=>['Inicio','◫'],'records'=>['Registros','▤'],'reservations'=>['Programación','▦'],'profile'=>['Mi perfil','♙']];foreach($nav as $p=>$n):?><a class="<?=$page===$p?'active':''?>" href="<?=e(url($p))?>"><span><?=$n[1]?></span><?=e($n[0])?></a><?php endforeach;?></nav><div class="side-bottom"><small>Versión 2.9</small><form method="post"><?=csrf()?><input type="hidden" name="action" value="logout"><button class="logout">Cerrar sesión</button></form></div></aside><?php endif;?><div class="shell <?=$page==='login'?'login-shell':''?>"><?php if($page!=='login'):?><header class="topbar"><span>GESTIÓN DE FLOTA</span><div class="topbar-actions"><span><?=e(date('d/m/Y'))?></span><form method="post" class="inline mobile-logout"><?=csrf()?><input type="hidden" name="action" value="logout"><button class="button secondary small">Cerrar sesión</button></form></div></header><?php if(isAdmin()){ $globalVerificationSnapshot=verificationSnapshot(); if($globalVerificationSnapshot['due']) echo verificationNoticeHtml($globalVerificationSnapshot); } ?><?php endif;?><main id="main"><?php if(isExternal()){$u=currentUser();$st=licenseState($u);if($st['expired'])echo '<div class="notice error"><strong>Licencia vencida.</strong> Actualiza tu perfil para poder registrar nuevas bitácoras.</div>';elseif($st['soon'])echo '<div class="notice error"><strong>Licencia próxima a vencer.</strong> Vence el '.e(displayDate($u['license_expires'])).' ('.$st['days'].' días).</div>';} ?><?php } ?>
<?php function renderFooter(): void {echo '</main><footer class="footer">Control vehicular · Versión 2.9</footer></div></body></html>';}
function pageTitle(string $t,string $s='',string $a=''):void{echo '<div class="page-title"><div><h1>'.e($t).'</h1>'.($s?'<p>'.e($s).'</p>':'').'</div>'.$a.'</div>';}
function linkButton(string $text,string $page,array $p=[],string $class=''):string{return '<a class="button '.e($class).'" href="'.e(url($page,$p)).'">'.e($text).'</a>';}
function inputField(string $n,string $l,mixed $v='',string $type='text',string $attrs=''):void{
 if($type==='date'){$type='text';$v=displayDate($v);$attrs=trim($attrs.' placeholder="DD/MM/AAAA" inputmode="numeric" autocomplete="off"');}
 elseif($type==='month'){$type='text';$v=displayMonth($v);$attrs=trim($attrs.' placeholder="MM/AAAA" inputmode="numeric" autocomplete="off"');}
 echo '<label class="field"><span>'.e($l).'</span><input name="'.e($n).'" type="'.e($type).'" value="'.e($v).'" '.$attrs.'></label>';
}
function hidden(string $n,mixed $v):void{echo '<input type="hidden" name="'.e($n).'" value="'.e($v).'">';}
function vehicleSelect(mixed $sel=0,bool $all=false):void{echo '<label class="field"><span>Vehículo</span><select name="vehicle_id" '.(!$all?'required':'').'>';echo $all?'<option value="0">Todos</option>':'<option value="">Selecciona</option>';foreach(rows('SELECT * FROM vehicles ORDER BY economic_number') as $v)echo '<option value="'.$v['id'].'" '.((int)$sel===(int)$v['id']?'selected':'').'>'.e($v['economic_number'].' · '.$v['brand'].' '.$v['model'].' · '.$v['plates']).'</option>';echo '</select></label>';}
function warningBox():void{global $warnings,$warningPayload;if(!$warnings)return;echo '<div class="notice warning"><strong>Advertencias de la bitácora</strong><ul>';foreach($warnings as $w)echo '<li>'.e($w).'</li>';echo '</ul><label class="check"><input type="checkbox" name="accept_warnings" value="1" required> Confirmo que revisé las advertencias.</label>';hidden('warning_token',warningToken($warningPayload,$warnings));hidden('confirm_pending','1');echo '</div>';}
function deleteForm(string $a,int $id,string $msg,array $extra=[]):void{echo '<form method="post" class="inline" data-confirm="'.e($msg).'">'.csrf();hidden('action',$a);hidden('id',$id);foreach($extra as $k=>$v)hidden($k,$v);echo '<button class="button danger small">Eliminar</button></form>';}
function loginView():void{echo '<div class="login-brand"><span class="brand-mark">CV</span><h1>Control vehicular</h1><p>Inicia sesión para acceder al sistema.</p></div><section class="panel login-card">';echo '<form method="post">'.csrf().'<h2>Iniciar sesión</h2>';inputField('username','Usuario','','text','required autocomplete="username"');inputField('password','Contraseña','','password','required autocomplete="current-password"');hidden('auth_action','login');echo '<button class="button">Ingresar</button></form>';echo '<div class="register-prompt"><p>¿Es tu primer acceso?</p>'.linkButton('Registrarse','login',['register'=>1],'secondary').'</div></section>';if(!empty($_GET['register'])){echo '<section class="panel register-panel"><h2>Registro de usuario externo</h2><p class="help">Ingresa tus datos de conductor; quedarán asociados a tu perfil y se utilizarán para autocompletar tus bitácoras.</p><form method="post">'.csrf();inputField('username','Usuario','','text','required maxlength="80" autocomplete="username"');inputField('password','Contraseña','','password','required minlength="6" autocomplete="new-password"');inputField('driver_name','Nombre del conductor','','text','required maxlength="150"');inputField('license_number','Número de licencia','','text','required maxlength="80"');inputField('license_expires','Fecha de vencimiento de licencia','','date','required');hidden('auth_action','register');echo '<button class="button">Crear cuenta</button> '.linkButton('Volver a ingresar','login',[],'secondary').'</form></section>';}}
function dashboardView():void{if(isExternal()){userDashboardView();return;}pageTitle('Panel de vehículos','Entra a un vehículo para administrar sus bitácoras.',linkButton('+ Nuevo vehículo','vehicle'));$snapshot=verificationSnapshot();$vs=rows('SELECT * FROM vehicles ORDER BY economic_number');echo '<section class="vehicle-grid">';foreach($vs as $v){$state=$snapshot['vehicles'][$v['id']];echo '<article class="vehicle-card" id="vehicle-'.(int)$v['id'].'" data-verification-vehicle="'.(int)$v['id'].'"><a class="vehicle-main" href="'.e(url('vehicle',['id'=>$v['id']])).'"><span class="economic">'.e($v['economic_number']).'</span><h3>'.e($v['brand'].' '.$v['model'].' '.$v['model_year']).'</h3><div class="plate">'.e($v['plates']).'</div><p>'.e($v['department']).'</p><strong>Abrir panel ↗</strong></a><div class="vehicle-verifications">'.verificationCardHtml($state).'</div></article>';}echo '</section>';}
function userDashboardView():void{$u=currentUser();$st=licenseState($u);pageTitle('Inicio','Selecciona un vehículo para registrar una bitácora.');echo '<section class="vehicle-grid">';foreach(rows('SELECT * FROM vehicles ORDER BY economic_number') as $v){echo '<article class="vehicle-card"><div class="card-top"><span class="economic">'.e($v['economic_number']).'</span></div><h3>'.e($v['brand'].' '.$v['model'].' '.$v['model_year']).'</h3><p>'.e($v['plates'].' · '.$v['department']).'</p>';if($st['expired'])echo '<span class="button secondary disabled">Licencia vencida</span>';else echo linkButton('Registrar bitácora','trip_form',['vehicle_id'=>$v['id']]);echo '</article>';}echo '</section>';}
function vehiclesView():void{requireAdmin();pageTitle('Vehículos','Flota registrada.',linkButton('+ Nuevo vehículo','vehicle'));echo '<section class="panel table-wrap"><table><tr><th>No.</th><th>Vehículo</th><th>Año</th><th>Departamento</th><th>Placas</th><th></th></tr>';foreach(rows('SELECT * FROM vehicles ORDER BY economic_number') as $v)echo '<tr><td>'.e($v['economic_number']).'</td><td>'.e($v['brand'].' '.$v['model']).'</td><td>'.e($v['model_year']).'</td><td>'.e($v['department']).'</td><td>'.e($v['plates']).'</td><td>'.linkButton('Abrir','vehicle',['id'=>$v['id']],'secondary small').'</td></tr>';echo '</table></section>';}
function vehicleView():void{requireAdmin();$id=(int)($_GET['id']??0);$old=$id?need('vehicles',$id):[];$v=$_SERVER['REQUEST_METHOD']==='POST'?$_POST:$old;pageTitle($id?'Vehículo '.$old['economic_number']:'Nuevo vehículo','Datos y registros del vehículo.',linkButton('Volver','vehicles',[],'secondary'));echo '<form method="post" class="panel">'.csrf();hidden('action','vehicle_save');hidden('id',$id);echo '<div class="form-grid">';foreach(['brand'=>'Marca','model'=>'Modelo','plates'=>'Placas','economic_number'=>'No. económico','responsible'=>'Responsable','department'=>'Departamento'] as $f=>$l)inputField($f,$l,$v[$f]??'','text','required');inputField('model_year','Año del modelo',$v['model_year']??date('Y'),'number','required min="1900" max="2100"');inputField('baseline_date','Fecha referencia',$v['baseline_date']??date('Y-m-d'),'date','required');inputField('baseline_km','Km referencia',isset($v['baseline_km'])?num($v['baseline_km'],0):'','number','required min="0" step="1"');echo '</div><button class="button">Guardar vehículo</button></form>';if(!$id)return;vehicleInactivePanel($id);adminInlineTripForm($old);vehicleTripsPanel($id);verificationHistoryView($id);}

function vehicleInactivePanel(int $vid):void{echo '<section class="panel"><div class="section-heading"><h2>Periodos de inactividad</h2>'.linkButton('+ Nuevo periodo','period',['vehicle_id'=>$vid]).'</div>';foreach(rows('SELECT * FROM inactive_periods WHERE vehicle_id=? ORDER BY start_date DESC',[$vid]) as $p){echo '<div class="actions" style="margin-bottom:10px"><span>#'.(int)$p['id'].' · '.e(displayDate($p['start_date']).' → '.($p['end_date']?displayDate($p['end_date']):'abierto').' · '.$p['reason'].($p['notes']?' · '.$p['notes']:'')).'</span>'.linkButton('Editar','period',['id'=>$p['id']],'secondary small').'<form method="post" class="inline" data-confirm="Este periodo de inactividad será eliminado. ¿Continuar?">'.csrf().'<input type="hidden" name="action" value="period_delete"><input type="hidden" name="id" value="'.(int)$p['id'].'"><input type="hidden" name="vehicle_id" value="'.(int)$vid.'"><button class="button danger small">Eliminar</button></form></div>';}echo '</section>';}
function adminInlineTripForm(array $vehicle):void{$last=row('SELECT km_end FROM trips WHERE vehicle_id=? ORDER BY departure_at DESC,id DESC LIMIT 1',[$vehicle['id']]);echo '<section class="panel"><h2>Agregar bitácora</h2><form method="post" id="trip-form">'.csrf();hidden('action','trip_save');hidden('id',0);hidden('vehicle_id',$vehicle['id']);warningBox();echo '<div class="readonly-grid"><div><small>Vehículo</small><strong>'.e($vehicle['economic_number'].' · '.$vehicle['brand'].' '.$vehicle['model'].' · '.$vehicle['plates']).'</strong></div></div><div class="form-grid">';inputField('request_date','Fecha',date('Y-m-d'),'date','required');inputField('departure_time','Hora salida','','time','required');inputField('arrival_time','Hora llegada','','time','required');inputField('km_start','Km inicial',isset($last['km_end'])?num($last['km_end'],0):num($vehicle['baseline_km'],0),'number','required step="1"');inputField('km_end','Km final','','number','required step="1"');inputField('driver','Conductor','','text','required');inputField('purpose','Comisión','','text','required');inputField('requester','Solicitante','','text','required');echo '<label class="field wide"><span>Observaciones</span><textarea name="observations" maxlength="1000"></textarea></label></div><button class="button">Guardar bitácora</button></form></section>';}
function vehicleTripsPanel(int $vid):void{$q=trim((string)($_GET['q']??''));$args=[$vid];$where='t.vehicle_id=?';if($q!==''){$where.=' AND (t.driver LIKE ? OR t.purpose LIKE ? OR t.requester LIKE ? OR t.id=?)';$like='%'.$q.'%';array_push($args,$like,$like,$like,(int)ltrim($q,'#'));}echo '<section class="panel"><div class="section-heading"><h2>Bitácoras de este vehículo</h2></div><form method="get" class="search-form">';hidden('page','vehicle');hidden('id',$vid);inputField('q','Buscar por ID, conductor, comisión o solicitante',$q,'search');echo '<button class="button">Buscar</button></form>';tripTable(rows('SELECT t.*,v.economic_number,v.plates FROM trips t JOIN vehicles v ON v.id=t.vehicle_id WHERE '.$where.' ORDER BY t.departure_at DESC,t.id DESC',$args),true);echo '</section>';}
function tripFormView():void{
 $id=(int)($_GET['id']??0);$old=$id?need('trips',$id):[];if($old&&!canEditTrip($old))throw new RuntimeException('Solo puedes editar tus propios registros.');if(isExternal())assertLicenseValid();
 $pending=pendingTrip();$usePending=$pending&&((int)$pending['id']===$id);$vid=(int)($usePending?$pending['data']['vehicle_id']:($old['vehicle_id']??$_GET['vehicle_id']??0));$vehicle=need('vehicles',$vid);$u=currentUser();$v=$old;$warnings=[];$warningPayload=[];
 if($usePending){$v=$pending['data'];$v['departure_time']=substr($v['departure_at'],11,5);$v['arrival_time']=substr($v['arrival_at'],11,5);$warnings=$pending['warnings'];$warningPayload=[$pending['data'],(int)$pending['id']];}
 elseif($id){$v['departure_time']=substr($old['departure_at'],11,5);$v['arrival_time']=substr($old['arrival_at'],11,5);}
 else{$last=row('SELECT km_end FROM trips WHERE vehicle_id=? ORDER BY departure_at DESC,id DESC LIMIT 1',[$vid]);$driver=$u['driver_name']??'';$v=['vehicle_id'=>$vid,'request_date'=>date('Y-m-d'),'driver'=>$driver,'requester'=>$driver,'km_start'=>$last['km_end']??$vehicle['baseline_km']];}
 $GLOBALS['warnings']=$warnings;$GLOBALS['warningPayload']=$warningPayload;
 pageTitle($usePending?'Confirmar bitácora':($id?'Editar bitácora #'.$id:'Nueva bitácora'),$vehicle['economic_number'].' · '.$vehicle['brand'].' '.$vehicle['model'].' · '.$vehicle['plates'],linkButton('Volver',isAdmin()?'vehicle':'dashboard',isAdmin()?['id'=>$vid]:[],'secondary'));
 echo '<form method="post" class="panel" id="trip-form">'.csrf();hidden('action','trip_save');hidden('id',$id);hidden('vehicle_id',$vid);warningBox();echo '<div class="readonly-grid"><div><small>Conductor</small><strong>'.e(isExternal()?($u['driver_name']??''):$v['driver']??'').'</strong></div><div><small>Vehículo</small><strong>'.e($vehicle['economic_number'].' · '.$vehicle['brand'].' '.$vehicle['model'].' · '.$vehicle['plates']).'</strong></div></div>';
 if(isExternal())echo '<p class="help km-reference-note"><strong>Importante:</strong> los kilómetros mostrados son una referencia del último registro del vehículo; son opcionales y no necesariamente corresponden a los kilómetros que requieres registrar en esta bitácora.</p>';
 if(isAdmin())inputField('driver','Conductor',$v['driver']??'','text','required');else hidden('driver',$u['driver_name']);echo '<div class="form-grid">';inputField('request_date','Fecha',$v['request_date']??date('Y-m-d'),'date','required');inputField('departure_time','Hora salida',$v['departure_time']??'','time','required');inputField('arrival_time','Hora llegada',$v['arrival_time']??'','time','required');inputField('km_start','Km inicial',isset($v['km_start'])?num($v['km_start'],0):'','number','required step="1"');inputField('km_end','Km final',isset($v['km_end'])?num($v['km_end'],0):'','number','required step="1"');inputField('purpose','Comisión',$v['purpose']??'','text','required');inputField('requester','Solicitante del servicio',$v['requester']??($u['driver_name']??''),'text','required');echo '<label class="field wide"><span>Observaciones</span><textarea name="observations" maxlength="1000">'.e($v['observations']??'').'</textarea></label></div><button class="button">'.($usePending?'Confirmar y guardar bitácora':'Guardar bitácora').'</button></form>';
}
function tripTable(array $data,bool $admin=false):void{echo '<div class="table-wrap"><table><tr><th>ID</th><th>Vehículo</th><th>Fecha</th><th>Conductor</th><th>Km</th><th>Comisión</th><th>Acciones</th></tr>';foreach($data as $t){echo '<tr><td>#'.$t['id'].'</td><td>'.e($t['economic_number']??'').'</td><td>'.e(displayDate(substr($t['departure_at'],0,10)).' '.substr($t['departure_at'],11,5)).'</td><td>'.e($t['driver']).'</td><td>'.e(num($t['km_start'],0).' → '.num($t['km_end'],0)).'</td><td>'.e($t['purpose']).'</td><td><div class="actions">'.linkButton('Ver','trip',['id'=>$t['id']],'secondary small');if(canEditTrip($t))echo linkButton('Editar','trip_form',['id'=>$t['id']],'secondary small');if($admin)deleteForm('trip_delete',(int)$t['id'],'¿Eliminar esta bitácora?');echo '</div></td></tr>';}if(!$data)echo '<tr><td colspan="7" class="empty">Sin registros.</td></tr>';echo '</table></div>';}
function tripView():void{$t=need('trips',(int)($_GET['id']??0));if(!canViewTrip($t))throw new RuntimeException('No tienes acceso a este registro.');$v=need('vehicles',(int)$t['vehicle_id']);pageTitle('Bitácora #'.$t['id'],$v['economic_number'].' · '.$v['brand'].' '.$v['model'],(canEditTrip($t)?linkButton('Editar','trip_form',['id'=>$t['id']]):'').' '.((isAdmin()||(int)$t['user_id']===currentUserId())?linkButton('Descargar XLSX','export',['kind'=>'trip_template','id'=>$t['id']],'secondary'):''));echo '<section class="panel detail-grid"><div><small>Conductor</small><strong>'.e($t['driver']).'</strong></div><div><small>Solicitante</small><strong>'.e($t['requester']).'</strong></div><div><small>Salida</small><strong>'.e(displayDate($t['departure_at']).' '.substr($t['departure_at'],11,5)).'</strong></div><div><small>Llegada</small><strong>'.e(displayDate($t['arrival_at']).' '.substr($t['arrival_at'],11,5)).'</strong></div><div><small>Km</small><strong>'.e(num($t['km_start'],0).' → '.num($t['km_end'],0)).'</strong></div><div><small>Comisión</small><strong>'.e($t['purpose']).'</strong></div><div class="wide"><small>Observaciones</small><strong>'.e($t['observations']).'</strong></div></section>';}
function recordsView():void{if(!isExternal())throw new RuntimeException('Sección de usuarios.');$q=trim((string)($_GET['q']??''));$args=[currentUserId(),currentUserId()];$where='(t.user_id=? OR t.vehicle_id IN (SELECT DISTINCT vehicle_id FROM trips WHERE user_id=?))';if($q!==''){$where.=' AND (t.driver LIKE ? OR t.purpose LIKE ? OR v.economic_number LIKE ? OR t.id=?)';$like='%'.$q.'%';array_push($args,$like,$like,$like,(int)ltrim($q,'#'));}pageTitle('Registros','Consulta tus registros y los de vehículos que has utilizado.');echo '<section class="panel"><form method="get" class="search-form">';hidden('page','records');inputField('q','Buscar',$q,'search','placeholder="ID, vehículo, conductor o comisión"');echo '<button class="button">Buscar</button></form>';tripTable(rows('SELECT t.*,v.economic_number,v.plates FROM trips t JOIN vehicles v ON v.id=t.vehicle_id WHERE '.$where.' ORDER BY t.departure_at DESC,t.id DESC',$args));echo '</section>';}
function profileView():void{$u=currentUser();pageTitle('Mi perfil','Estos datos se autocompletan en tus bitácoras.');echo '<form method="post" class="panel">'.csrf();hidden('action','profile_save');echo '<div class="form-grid">';inputField('driver_name','Nombre del conductor',$u['driver_name'],'text','required');inputField('license_number','Número de licencia',$u['license_number'],'text','required');inputField('license_expires','Vencimiento',$u['license_expires'],'date','required');echo '</div><button class="button">Guardar cambios</button></form>';}
function fuelFields(array $v):void{vehicleSelect($v['vehicle_id']??0);inputField('fuel_date','Fecha',$v['fuel_date']??date('Y-m-d'),'date','required');inputField('liters','Litros',$v['liters']??'','number','required step="0.001" min="0.001"');inputField('amount','Monto total pagado',$v['amount']??'','number','required step="0.01" min="0"');echo '<label class="field"><span>Forma de pago</span><select name="payment_method" id="payment-method">';foreach(['Efectivo','Tarjeta','Vale'] as $m)echo '<option '.(($v['payment_method']??'')===$m?'selected':'').'>'.$m.'</option>';echo '</select></label>';inputField('card_last5','Últimos 5 dígitos (solo tarjeta)',$v['card_last5']??'','text','inputmode="numeric" maxlength="5" pattern="[0-9]{5}"');}
function fuelView():void{requireAdmin();$id=(int)($_GET['id']??0);$old=$id?need('fuel_loads',$id):[];$v=$_SERVER['REQUEST_METHOD']==='POST'?$_POST:$old;pageTitle('Gasolina','Cargas independientes de las bitácoras.',linkButton('+ Nueva carga','fuel'));if($id||isset($_GET['new'])){echo '<form method="post" class="panel">'.csrf();hidden('action','fuel_save');hidden('id',$id);echo '<div class="form-grid">';fuelFields($v);echo '</div><button class="button">Guardar carga</button></form>';}else echo '<p>'.linkButton('+ Registrar carga','fuel',['new'=>1]).'</p>';$month=monthValue($_GET['month']??date('Y-m'),'Mes');$vid=(int)($_GET['vehicle_id']??0);echo '<section class="panel"><form method="get" class="filter-form">';hidden('page','fuel');vehicleSelect($vid,true);inputField('month','Mes',$month,'month','required');echo '<button class="button">Consultar</button></form>';[$a,$b]=monthBounds($month);$args=[$a,$b];$where='f.fuel_date>=? AND f.fuel_date<?';if($vid){$where.=' AND f.vehicle_id=?';$args[]=$vid;}$rows=rows('SELECT f.*,v.economic_number,v.brand,v.model FROM fuel_loads f JOIN vehicles v ON v.id=f.vehicle_id WHERE '.$where.' ORDER BY f.fuel_date DESC,f.id DESC',$args);echo '<div class="table-wrap"><table><tr><th>Fecha</th><th>Vehículo</th><th>Litros</th><th>Monto</th><th>Pago</th><th></th></tr>';foreach($rows as $f)echo '<tr><td>'.e(displayDate($f['fuel_date'])).'</td><td>'.e($f['economic_number'].' · '.$f['brand'].' '.$f['model']).'</td><td>'.num($f['liters'],3).'</td><td>$'.num($f['amount']).'</td><td>'.e($f['payment_method'].($f['card_last5']?' · '.$f['card_last5']:'' )).'</td><td class="actions">'.linkButton('Editar','fuel',['id'=>$f['id']],'secondary small').'<form method="post" class="inline" data-confirm="Esta carga de gasolina se eliminará definitivamente. ¿Continuar?">'.csrf().'<input type="hidden" name="action" value="fuel_delete"><input type="hidden" name="id" value="'.(int)$f['id'].'"><button class="button danger small">Eliminar</button></form></td></tr>';echo '</table></div>';if($vid)echo '<p>'.linkButton('Descargar concentrado mensual','export',['kind'=>'gas_month','month'=>$month,'vehicle_id'=>$vid]).'</p>';echo '</section>';}
function periodView():void{requireAdmin();$id=(int)($_GET['id']??0);$old=$id?need('inactive_periods',$id):[];$vid=(int)($old['vehicle_id']??$_GET['vehicle_id']??0);$v=$_SERVER['REQUEST_METHOD']==='POST'?$_POST:$old;pageTitle('Periodo de inactividad','',linkButton('Volver','vehicle',['id'=>$vid],'secondary'));echo '<form method="post" class="panel">'.csrf();hidden('action','period_save');hidden('id',$id);hidden('vehicle_id',$vid);inputField('start_date','Desde',$v['start_date']??date('Y-m-d'),'date','required');inputField('end_date','Hasta',$v['end_date']??'','date');echo '<label class="field"><span>Estado</span><select name="reason">';foreach(['DESCOMPUESTO Y EN LAS INSTALACIONES DEL IMPLAN','RECIBIENDO SERVICIO EN EL TALLER MECÁNICO','NO DISPONIBLE'] as $reason)echo '<option value="'.e($reason).'" '.(($v['reason']??'')===$reason?'selected':'').'>'.e($reason).'</option>';echo '</select></label>';inputField('notes','Notas',$v['notes']??'');echo '<button class="button">Guardar</button></form>';}
function reservationsView():void{pruneReservations();pageTitle('Programación','Puedes ver las programaciones de otros usuarios y administrar las tuyas.',linkButton('+ Programar','reservation_form'));$rows=rows('SELECT r.*,v.economic_number,v.brand,v.model,u.driver_name owner FROM reservations r JOIN vehicles v ON v.id=r.vehicle_id LEFT JOIN users u ON u.id=r.user_id WHERE r.scheduled_at>=? ORDER BY r.scheduled_at',[date('Y-m-d H:i:s')]);echo '<section class="panel table-wrap"><table><tr><th>Vehículo</th><th>Fecha y hora</th><th>Usuario</th><th>Acciones</th></tr>';foreach($rows as $r){$mine=isAdmin()||(isExternal()&&(int)$r['user_id']===currentUserId());echo '<tr><td>'.e($r['economic_number'].' · '.$r['brand'].' '.$r['model']).'</td><td>'.e(displayDate(substr($r['scheduled_at'],0,10)).' '.substr($r['scheduled_at'],11,5)).'</td><td>'.e($r['owner']??'Administrador').'</td><td>';if($mine){echo linkButton('Editar','reservation_form',['id'=>$r['id']],'secondary small');deleteForm('reservation_cancel',(int)$r['id'],'¿Eliminar esta programación?',['version'=>$r['version']]);}else echo 'Solo consulta';echo '</td></tr>';}echo '</table></section>';}
function reservationFormView():void{$id=(int)($_GET['id']??0);$old=$id?need('reservations',$id):[];if($old&&isExternal()&&(int)$old['user_id']!==currentUserId())throw new RuntimeException('Solo puedes editar tus programaciones.');$v=$old;if($old){$v['scheduled_date']=substr($old['scheduled_at'],0,10);$v['scheduled_time']=substr($old['scheduled_at'],11,5);}pageTitle($id?'Editar programación':'Programar vehículo','',linkButton('Volver','reservations',[],'secondary'));echo '<form method="post" class="panel">'.csrf();hidden('action','reservation_save');hidden('id',$id);hidden('version',$v['version']??1);echo '<div class="form-grid">';vehicleSelect($v['vehicle_id']??0);inputField('scheduled_date','Fecha',$v['scheduled_date']??date('Y-m-d'),'date','required');inputField('scheduled_time','Hora',$v['scheduled_time']??'','time','required');echo '</div><button class="button">Guardar</button></form>';}
function reportsView():void{requireAdmin();pageTitle('Concentrados','Conserva los concentrados mensuales y agrega el anual de gasolina.');$month=monthValue($_GET['month']??date('Y-m'),'Mes');$year=(int)($_GET['year']??date('Y'));$vid=(int)($_GET['vehicle_id']??0);echo '<section class="panel"><h2>Mensual</h2><form method="get" class="filter-form">';hidden('page','reports');inputField('month','Mes',$month,'month');vehicleSelect($vid,true);echo '<button class="button">Actualizar</button></form><p>'.linkButton('Concentrado general XLSX','export',['kind'=>'general','month'=>$month]);if($vid)echo ' '.linkButton('Concentrado del vehículo','export',['kind'=>'vehicle','month'=>$month,'vehicle_id'=>$vid],'secondary');echo '</p><hr><h2>Anual de gasolina</h2><form method="get" action="index.php">';hidden('page','export');hidden('kind','annual');inputField('year','Año',$year,'number','min="2000" max="2100"');echo '<button class="button">Descargar dinero + litros</button></form></section>';}
function gapsView():void{requireAdmin();$month=monthValue($_GET['month']??date('Y-m'),'Mes');pageTitle('Kilómetros pendientes','Huecos entre lecturas conocidas.');echo '<section class="panel"><form method="get">';hidden('page','gaps');inputField('month','Mes',$month,'month');echo '<button class="button">Consultar</button></form><div class="table-wrap"><table><tr><th>Vehículo</th><th>Tipo</th><th>Rango</th><th>Km</th></tr>';foreach(rows('SELECT * FROM vehicles ORDER BY economic_number') as $v){$all=rows('SELECT * FROM trips WHERE vehicle_id=? ORDER BY departure_at,id',[$v['id']]);foreach(missingRanges($v,$all,$month) as $g)echo '<tr><td>'.e($v['economic_number']).'</td><td>'.e($g['type']).'</td><td>'.e($g['from'].' → '.$g['to']).'</td><td>'.num($g['km'],0).'</td></tr>';}echo '</table></div></section>';}
function importView():void{requireAdmin();global $importPreview;$importPreview??=$_SESSION['import_review']??null;pageTitle('Importar registros','Importa bitácoras y cargas históricas desde XLSX.',linkButton('Descargar plantilla','export',['kind'=>'template'],'secondary'));echo '<section class="panel"><form method="post" enctype="multipart/form-data">'.csrf();hidden('action','import_preview');inputField('xlsx','Archivo XLSX','','file','required accept=".xlsx"');echo '<button class="button">Revisar</button></form></section>';if($importPreview)echo '<section class="panel"><p>Bitácoras: '.$importPreview['trips'].' · Gasolina: '.$importPreview['fuel'].' · Omitidos: '.$importPreview['skipped'].'</p><form method="post">'.csrf().'<input type="hidden" name="action" value="import_commit"><button class="button">Confirmar importación</button></form></section>';}
function userEditView():void{requireAdmin();$id=(int)($_GET['id']??0);$u=need('users',$id);pageTitle('Editar usuario','Modifica los datos de la cuenta externa.',linkButton('Volver','users',[],'secondary'));echo '<form method="post" class="panel">'.csrf();hidden('action','user_save');hidden('user_id',$id);echo '<div class="form-grid">';inputField('username','Usuario',$u['username'],'text','required maxlength="80"');inputField('driver_name','Nombre del conductor',$u['driver_name'],'text','required maxlength="150"');inputField('license_number','Número de licencia',$u['license_number'],'text','required maxlength="80"');inputField('license_expires','Vencimiento',$u['license_expires'],'date','required');inputField('password','Nueva contraseña','','password','minlength="6" autocomplete="new-password"');echo '</div><p class="help">Deja la contraseña vacía para conservar la actual.</p><button class="button">Guardar cambios</button></form>';}
function usersView():void{requireAdmin();pageTitle('Usuarios externos','Gestiona las cuentas y los datos de los conductores.');echo '<section class="panel table-wrap"><table><tr><th>Usuario</th><th>Conductor</th><th>Licencia</th><th>Vencimiento</th><th>Estado</th><th>Acciones</th></tr>';foreach(rows('SELECT * FROM users ORDER BY driver_name') as $u){$s=licenseState($u);echo '<tr><td>'.e($u['username']).'</td><td>'.e($u['driver_name']).'</td><td>'.e($u['license_number']).'</td><td>'.e(displayDate($u['license_expires'])).'</td><td><span class="badge '.($s['expired']?'red':($s['soon']?'amber':'green')).'">'.($s['expired']?'Vencida':($s['soon']?'Por vencer':'Vigente')).'</span></td><td class="actions">'.linkButton('Editar','user_edit',['id'=>$u['id']],'secondary small').'<form method="post" class="inline" data-confirm="Se eliminará la cuenta y se conservarán sus bitácoras y programaciones. ¿Continuar?">'.csrf().'<input type="hidden" name="action" value="user_delete_keep"><input type="hidden" name="user_id" value="'.(int)$u['id'].'"><button class="button danger small">Eliminar y conservar registros</button></form><form method="post" class="inline" data-confirm="Se eliminarán la cuenta, sus bitácoras y sus programaciones. Esta acción no se puede deshacer. ¿Continuar?">'.csrf().'<input type="hidden" name="action" value="user_delete_all"><input type="hidden" name="user_id" value="'.(int)$u['id'].'"><button class="button danger small">Eliminar todo</button></form></td></tr>';}echo '</table></section>';}
